#!/usr/bin/env python3
"""Track C: merge the parts into heading.json and print the full set of tables as markdown on stdout (every table is generated from the JSON, no hand-typed numbers)."""
import os, json, numpy as np
O = '/root/rasr-pairuav/outputs/supp/trackC'
J = lambda f: json.load(open(f'{O}/{f}')) if os.path.exists(f'{O}/{f}') else None
sites, cpu, ret, sens, real = J('sites.json'), J('part_cpu.json'), J('part_retrain.json'), J('part_sens.json'), J('part_real.json')
H = dict(sites=sites, test_set=cpu, site_disjoint_retraining=ret, photometric_sensitivity=sens, real_photographs=real); json.dump(H, open(f'{O}/heading.json', 'w'), indent=1)
p1 = lambda v: f'{100 * v:.1f}'; L = []; A = L.append
def tab(head, rows, align=None):
    A('| ' + ' | '.join(head) + ' |'); A('|' + '|'.join((align or ['---'] + ['---:'] * (len(head) - 1))) + '|'); [A('| ' + ' | '.join(str(c) for c in r) + ' |') for r in rows]; A('')

A('# Track C - the absolute-heading prior\n')
A('All numbers are generated by `supp/trackC/*.py` from archived predictions and from the re-trainings of this track; `heading.json` holds every value. Pose metrics use `supp/common.py`. Geometry (Stage I / Stage II relative pose) is never changed here: only the heading that rotates the levelled displacement into east-north-up (ENU).\n')

# ------------------------------------------------------------------ protocol
A('## 1. Protocol\n')
A(f"- **Test pairs**: the {cpu['n_pairs']:,} test pairs of Tables 2-3 ({cpu['n_buildings']} buildings). \"Heading\" = absolute heading of the source camera *a*, clockwise from north; error = |wrap(estimate - truth)| in degrees. Confidence intervals: 95 %, bootstrap over buildings (1,000 resamples).")
A('- **Estimators** (all archived, nothing re-fitted in Sections 2, 3, 5, 6, 7): the *raw-view network* (ConvNeXt-S on the tilted view, 3 crops x 8 dihedral views) and the *nadir-rectified network* (ConvNeXt-S on the view warped to nadir, 12 rotations x mirror), each giving a von Mises mean and concentration kappa per image. *Fused a+b* = Eq. 4 of the paper (image *a* and image *b* rotated by the estimated heading change, natural parameters summed). Stage I uses the raw-view network; Stage II sums both networks.')
A(f"- **Sites**: single-linkage clustering (5 km) of the mean camera position of the 1,412 buildings -> {sites['n_sites']} sites. Role of a building for the heading networks: train ({sites['train_buildings']}), val (10 % of the training buildings, never used to train them) or test ({sites['test_buildings']}). \"Training buildings in the same site\" counts the *train* role only. Test buildings by that count: " + ', '.join(f'{k}: {v}' for k, v in sites['test_buildings_by_site_n_train'].items()) + '.')
hs = sites['heldout_site_table']
A(f"- **Site-disjoint split** (Section 4): sites visited in a fixed random order (seed 0), added while their test buildings stay <= 35 % of all test buildings, stop at >= 25 %. Held-out sites: {sites['heldout_sites']} = {sites['test_buildings_heldout']} test buildings ({100 * sites['test_buildings_heldout'] / sites['test_buildings']:.0f} %), {sites['val_buildings_heldout']} val buildings; their {sites['train_buildings_removed']} training buildings are removed (of {sites['train_buildings']}). Size-matched control: {sites['control_buildings_removed']} training buildings removed at random (seed 0) from the sites that are *not* held out.")
tab(['held-out site', 'lat', 'lon', 'buildings', 'train (removed)', 'val', 'test'], [[r['site'], f"{r['lat']:.2f}", f"{r['lon']:.2f}", r['n'], r['n_train'], r['n_val'], r['n_test']] for r in hs])
if ret and ret.get('training'):
    A('- **Re-training recipe**: unchanged from `superglue_fusion/abs_heading_train2.py` (raw-view) and `stage2_imagination/bev_heading.py` (nadir-rectified): ConvNeXt-S (ImageNet-22k -> 1k weights), 10 epochs, batch 128, AdamW (lr 2e-4, weight decay 0.05), one-cycle schedule, von Mises NLL, same crops / dihedral or continuous-rotation augmentation and the same 24-view test-time averaging. The only implementation difference: the 128-image batch is passed in chunks of 12 with gradient accumulation before the single optimiser step (GPU-memory budget of the shared machine; no batch statistics in ConvNeXt, augmentation drawn per batch as before), and seeds are fixed (0).')
    tab(['run', 'training buildings', 'training images', 'optimiser steps', 'wall-clock (shared GPU)', 'peak GPU memory'], [[k, v['train_buildings'], f"{v['train_images']:,}", v.get('steps', v['epochs'] * (v['train_images'] // v['bs'])), f"{v['train_seconds'] / 60:.0f} min", f"{v['peak_mem_gb']:.1f} GB"] for k, v in ret['training'].items()])

# ------------------------------------------------------------------ error statistics
A('## 2. Error of the absolute-heading estimate (test pairs)\n')
E = cpu['error_statistics']
tab(['estimator', 'n', 'mean [95 % CI]', 'median [95 % CI]', 'P75', 'P90', 'P95', 'P99', '> 10 deg', '> 45 deg', '> 90 deg'],
    [[k, v['n'], f"{v['mean']:.2f} [{v['mean_ci'][0]:.2f}, {v['mean_ci'][1]:.2f}]", f"{v['median']:.2f} [{v['median_ci'][0]:.2f}, {v['median_ci'][1]:.2f}]", f"{v['p75']:.1f}", f"{v['p90']:.1f}", f"{v['p95']:.1f}", f"{v['p99']:.1f}", p1(v['gt10']) + ' %', p1(v['gt45']) + ' %', p1(v['gt90']) + ' %'] for k, v in E.items()])
A('Degrees. The distribution is heavy-tailed: the median is 4x smaller than the mean, and about 1.4 % of the pairs are off by more than 90 deg.\n')

# ------------------------------------------------------------------ where from
A('## 3. Where the error comes from\n'); b = cpu['bias_vs_noise']
A('### 3.1 Per-building bias vs per-image noise (Stage II ensemble, fused)\n')
A(f"Signed error of every pair = circular mean over the pairs of its building (bias) + remainder (noise); {b['buildings']} buildings, median {b['pairs_per_building_median']:.0f} pairs each.\n")
tab(['heading error kept', 'heading MAE', 'heading median', 'x MAE (m)', 'y MAE (m)', 'EPE mean (m)', 'EPE median (m)', 'SR_EPE@1m (%)'],
    [[nm, f"{b['heading_mae'][k]:.2f}" if k in b['heading_mae'] else '0', f"{b['heading_median'][k]:.2f}" if k in b['heading_median'] else '0', f"{b['enu'][e]['x_mae']:.2f}", f"{b['enu'][e]['y_mae']:.2f}", f"{b['enu'][e]['epe_mean']:.2f}", f"{b['enu'][e]['epe_med']:.2f}", p1(b['enu'][e]['sr_epe_1m'])]
     for nm, k, e in (('full error (as estimated)', 'full', 'full'), ('building bias only', 'building_bias_only', 'building_bias_only'), ('image noise only', 'image_noise_only', 'image_noise_only'), ('none (true heading)', 'none', 'true_heading'))])
ab = b['abs_building_bias']; sh = b['share_of_total_abs_error_from_worst_buildings']
A(f"|bias| per building: median {ab['median']:.2f} deg, mean {ab['mean']:.2f} deg; above 5 / 10 / 20 / 45 deg for {p1(ab['gt5'])} / {p1(ab['gt10'])} / {p1(ab['gt20'])} / {p1(ab['gt45'])} % of the buildings. The 5 / 10 / 15 / 29 worst buildings (of {b['buildings']}) carry {p1(sh['top5'])} / {p1(sh['top10'])} / {p1(sh['top15'])} / {p1(sh['top29'])} % of the summed absolute error; {b['buildings_with_mean_error_gt20']} buildings have a mean error above 20 deg.\n")

def fam(rows, title):
    A(title + '\n'); tab(['bin', 'test buildings', 'pairs', 'heading mean [95 % CI]', 'heading median', '> 10 deg', '> 45 deg', 'x / y MAE (m)', 'ENU: EPE median (m)', 'ENU: SR_EPE@1m (%) [CI]', 'camera frame: EPE median (m)', 'camera frame: SR_EPE@1m (%)'],
        [[r['bin'], r['buildings'], r['pairs'], f"{r['heading_s2']['mean']:.2f} [{r['heading_s2']['mean_ci'][0]:.2f}, {r['heading_s2']['mean_ci'][1]:.2f}]", f"{r['heading_s2']['median']:.2f}", p1(r['heading_s2']['gt10']) + ' %', p1(r['heading_s2']['gt45']) + ' %', f"{r['x_mae']:.2f} / {r['y_mae']:.2f}", f"{r['epe_enu_med']:.2f}",
          f"{p1(r['sr_epe_enu'])} [{p1(r['sr_epe_enu_ci'][0])}, {p1(r['sr_epe_enu_ci'][1])}]", f"{r['epe_cam_med']:.2f}", p1(r['sr_epe_cam'])] for r in rows])
A('### 3.2 Proximity of training buildings (archived networks, Stage II ensemble)\n')
fam(cpu['by_site_training_buildings'], '**By the number of training buildings in the same site**')
fam(cpu['by_distance_to_nearest_training_building'], '**By the distance from the test building to the nearest training building**')
c = cpu['building_level_correlation']
A(f"Building-level Spearman correlation of the mean heading error with the distance to the nearest training building: {c['spearman_meanerr_vs_distance']:+.2f}; with the number of training buildings in the site: {c['spearman_meanerr_vs_site_n_train']:+.2f} ({c['buildings']} buildings). The median test building is {c['m_to_nearest_train']['median']:.0f} m from a training building (P10 {c['m_to_nearest_train']['p10']:.0f} m, P90 {c['m_to_nearest_train']['p90']:.0f} m), i.e. closer than one image footprint (about 238 m x 134 m at nadir from 215 m), so most test views show ground that also appears in training views of a neighbouring building. The camera-frame columns show that the relative pose itself does not depend on this proximity.\n")
if 'single_image_raw_view_by_distance_test_and_val_northern' in cpu:
    A('Replication at the single-image level (raw-view network, northern-hemisphere buildings), on the test buildings and on the validation buildings (a random 10 % of the training buildings that the networks never saw):\n')
    f_ = lambda v: (f"{v['buildings']}", f"{v['images']}", (f"{v['mean']:.2f} / {v['median']:.2f}" if v['mean'] is not None else '-'), (p1(v['gt45']) + ' %' if v['gt45'] is not None else '-'))
    tab(['distance to nearest training building', 'test: buildings', 'images', 'mean / median', '> 45 deg', 'val: buildings', 'images', 'mean / median', '> 45 deg'], [[r['bin'], *f_(r['test']), *f_(r['val'])] for r in cpu['single_image_raw_view_by_distance_test_and_val_northern']])
if 'single_image_by_tilt' in cpu:
    A('Single-image error by camera tilt (archived networks; raw-view: all cached test images, nadir-rectified: pair sides):\n'); tab(['tilt from nadir', 'raw-view: n', 'mean / median', '> 45 deg', 'nadir-rectified: n', 'mean / median', '> 45 deg'], [[r['bin'], r['raw_view']['n'], f"{r['raw_view']['mean']:.2f} / {r['raw_view']['median']:.2f}", p1(r['raw_view']['gt45']) + ' %', r['nadir_rectified']['n'], f"{r['nadir_rectified']['mean']:.2f} / {r['nadir_rectified']['median']:.2f}", p1(r['nadir_rectified']['gt45']) + ' %'] for r in cpu['single_image_by_tilt']])
A('### 3.3 Hemisphere\n'); fam(cpu['by_hemisphere'], ''); ex = cpu['excluding_southern_hemisphere']
A(f"Signed error on the southern-hemisphere pairs: circular mean {cpu['southern_signed_error_circular_mean']:+.0f} deg. Southern-hemisphere buildings in the data: {sites['southern_hemisphere']['train']} train / {sites['southern_hemisphere']['val']} val / {sites['southern_hemisphere']['test']} test. Without those {cpu['n_pairs'] - ex['pairs']} pairs the Stage II heading error is mean {ex['heading']['mean']:.2f} / median {ex['heading']['median']:.2f} deg and ENU SR_EPE@1m is {p1(ex['sr_epe_enu'])} % (x / y MAE {ex['x_mae']:.2f} / {ex['y_mae']:.2f} m).\n")
A('### 3.4 Confidence: rejecting the pairs with the lowest fused concentration kappa (Stage II ensemble)\n'); rc = cpu['risk_coverage']
tab(['pairs kept', 'heading MAE', 'heading median', '> 10 deg', '> 45 deg', 'ENU: EPE median (m)', 'ENU: SR_EPE@1m (%)', 'camera frame SR_EPE@1m on the same pairs (%)', 'heading MAE with oracle ranking'],
    [[f"{100 * r['coverage']:.0f} %", f"{r['heading_mae']:.2f}", f"{r['heading_median']:.2f}", p1(r['heading_gt10']) + ' %', f"{100 * r['heading_gt45']:.2f} %", f"{r['epe_enu_med']:.2f}", p1(r['sr_epe_enu']), p1(r['sr_epe_cam_same_pairs']), f"{o['heading_mae']:.2f}"] for r, o in zip(rc['by_kappa'], rc['oracle'])])
A(f"Spearman(kappa, error) = {rc['spearman_kappa_vs_error']:+.2f}. Mean heading error per kappa octile (lowest to highest confidence): " + ', '.join(f"{r['heading_mae']:.1f}" for r in cpu['kappa_octiles']) + ' deg.\n')

# ------------------------------------------------------------------ site-disjoint retraining
if ret and any('B site-disjoint' in k for k in ret['subsets']['held-out sites']):
    A('## 4. Site-disjoint re-training\n')
    A('A = archived network (trained on all 1,010 training buildings, so it has seen *other* buildings of the held-out sites). B = site-disjoint (all training buildings of the held-out sites removed; 24 % fewer training buildings). Same test images and pairs for both. On the *other* sites both networks have seen the same neighbouring buildings, so the A-B difference there measures the effect of the smaller training set alone.\n')
    for sn in ('held-out sites', 'other sites'):
        o = ret['subsets'][sn]; A(f"**{sn}: {o['buildings']} test buildings, {o['pairs']} pairs** (camera frame, independent of the heading: EPE median {o['camera_frame']['epe_med']:.2f} m, SR_EPE@1m {p1(o['camera_frame']['sr_epe_1m'])} %)\n")
        rows = []
        for en, r in o.items():
            if not isinstance(r, dict) or 'fused_heading' not in r: continue
            h = r['fused_heading']; rows.append([en.replace(' | ', ', '), f"{h['mean']:.2f} [{r['fused_heading_mean_ci'][0]:.2f}, {r['fused_heading_mean_ci'][1]:.2f}]", f"{h['median']:.2f} [{r['fused_heading_median_ci'][0]:.2f}, {r['fused_heading_median_ci'][1]:.2f}]", f"{h['p90']:.1f}", p1(h['gt10']) + ' %', p1(h['gt45']) + ' %', f"{r['x_mae']:.2f} / {r['y_mae']:.2f}", f"{r['epe_mean']:.2f}", f"{r['epe_med']:.2f}",
                                         f"{p1(r['sr_epe_1m'])} [{p1(r['sr_epe_1m_ci'][0])}, {p1(r['sr_epe_1m_ci'][1])}]", p1(r['sr_5dof_1m_1deg']), f"{r['kappa_median']:.0f}"])
        tab(['heading source (fused a+b) for Stage II', 'heading mean [CI]', 'heading median [CI]', 'P90', '> 10 deg', '> 45 deg', 'x / y MAE (m)', 'EPE mean (m)', 'EPE median (m)', 'SR_EPE@1m (%) [CI]', '5-DoF (1 m, 1 deg) (%)', 'median kappa'], rows)
        A('Paired differences on the same pairs (building bootstrap):\n'); tab(['comparison', 'heading mean (deg)', 'heading median (deg)', 'SR_EPE@1m (points)', 'EPE median (m)'],
            [[k.replace(' | ', ', '), f"{v['heading_mean']['delta']:+.2f} [{v['heading_mean']['ci'][0]:+.2f}, {v['heading_mean']['ci'][1]:+.2f}]", f"{v['heading_median']['delta']:+.2f} [{v['heading_median']['ci'][0]:+.2f}, {v['heading_median']['ci'][1]:+.2f}]",
              f"{100 * v['sr_epe_1m']['delta']:+.1f} [{100 * v['sr_epe_1m']['ci'][0]:+.1f}, {100 * v['sr_epe_1m']['ci'][1]:+.1f}]", f"{v['epe_med']['delta']:+.2f} [{v['epe_med']['ci'][0]:+.2f}, {v['epe_med']['ci'][1]:+.2f}]"] for k, v in o['paired'].items()])
        A('Single image (pair sides):\n'); tab(['network', 'mean', 'median', 'P90', '> 10 deg', '> 45 deg'], [[k.replace('single image ', '').replace(' | ', ', '), f"{v['mean']:.2f}", f"{v['median']:.2f}", f"{v['p90']:.1f}", p1(v['gt10']) + ' %', p1(v['gt45']) + ' %'] for k, v in o.items() if k.startswith('single image')])
    A('**Per held-out site** (fused raw-view heading; signed error = circular mean, R = mean resultant length of the signed errors: 1 means one constant offset for the whole site)\n')
    rows = []; let = J('fig_heading_sitedisjoint_per_building_sites.json') or {}; let = {v: k for k, v in let.items()}
    for r in sorted(ret['heldout_per_site'], key=lambda q: -q['buildings']):
        a_, b_ = r.get('raw-view | A archived'), r.get('raw-view | B site-disjoint')
        rows.append([f"{let.get(r['site'], '')} (site {r['site']})", f"{r['lat']:.1f}, {r['lon']:.1f}", r['buildings'], r['pairs'], f"{r['km_to_nearest_kept_train']:.0f}", f"{a_['heading_mean']:.1f} / {a_['heading_median']:.1f}", f"{b_['heading_mean']:.1f} / {b_['heading_median']:.1f}", f"{b_['signed_circular_mean']:+.1f}", f"{b_['resultant_length']:.2f}",
                     f"{b_['mae_after_removing_site_offset']:.1f}", f"{b_['building_bias_min']:+.0f} .. {b_['building_bias_max']:+.0f}", f"{b_['building_bias_abs_median']:.1f}", f"{p1(a_['sr_epe_1m'])} -> {p1(b_['sr_epe_1m'])}"])
    tab(['held-out site (letter of the figure)', 'lat, lon', 'test buildings', 'pairs', 'km to nearest remaining training building', 'A: mean / median', 'B: mean / median', 'B: signed mean', 'B: R', 'B: MAE after removing the site offset', 'B: per-building bias range', 'B: abs. building bias, median', 'SR_EPE@1m ENU, A -> B (%)'], rows)
    if 'heldout_bias_vs_noise_B' in ret:
        q = ret['heldout_bias_vs_noise_B']; A(f"Site-disjoint network on the held-out sites: |per-building bias| median {q['abs_building_bias']['median']:.1f} deg, mean {q['abs_building_bias']['mean']:.1f} deg, above 10 / 20 / 45 deg for {p1(q['abs_building_bias']['gt10'])} / {p1(q['abs_building_bias']['gt20'])} / {p1(q['abs_building_bias']['gt45'])} % of the {q['buildings']} buildings; heading MAE {q['heading_mae']['full']:.1f} deg = {q['heading_mae']['building_bias_only']:.1f} (building bias only) vs {q['heading_mae']['image_noise_only']:.1f} (image noise only).\n")
    if 'heldout_by_distance_to_nearest_kept_training_building' in ret:
        A('Held-out pairs by the distance to the nearest *remaining* training building:\n'); tab(['distance', 'buildings', 'pairs', 'A: mean / median', 'B: mean / median', 'B: > 45 deg', 'SR_EPE@1m ENU, A -> B (%)'], [[r['bin'], r['buildings'], r['pairs'], f"{r['A']['mean']:.1f} / {r['A']['median']:.1f}", f"{r['B']['mean']:.1f} / {r['B']['median']:.1f}", p1(r['B']['gt45']) + ' %', f"{p1(r['A_sr_epe_1m'])} -> {p1(r['B_sr_epe_1m'])}"] for r in ret['heldout_by_distance_to_nearest_kept_training_building']])
    if 'heldout_risk_coverage_B' in ret:
        A('Is the failure detectable from the network\'s own confidence? Site-disjoint network on the held-out sites, pairs ranked by fused kappa:\n'); tab(['pairs kept', 'heading MAE', 'heading median', 'ENU SR_EPE@1m (%)'], [[f"{100 * r['coverage']:.0f} %", f"{r['heading_mae']:.1f}", f"{r['heading_median']:.1f}", p1(r['sr_epe_1m'])] for r in ret['heldout_risk_coverage_B']])
        A(f"Spearman(kappa, error) on the held-out sites: archived {ret['heldout_spearman_kappa_vs_error']['A']:+.2f}, site-disjoint {ret['heldout_spearman_kappa_vs_error']['B']:+.2f}.\n")
    if 'control_partial' in ret:
        cp = ret['control_partial']; A(f"**Size-matched control (partial).** A second run removed the same number of training buildings ({sites['control_buildings_removed']}), drawn at random from the sites that are *not* held out, so that it sees the held-out sites through their other buildings with the same amount of data as the site-disjoint run. It was stopped after {cp['epochs']} of 10 epochs to stay within the GPU budget of the shared machine, so it is reported only as an epoch-matched comparison of the monitoring numbers (identical schedule; single centre view, no test-time averaging; all cached test images):\n")
        tab(['epoch', 'site-disjoint: held-out sites, mean / median', 'control: held-out sites, mean / median', 'site-disjoint: other sites, mean / median', 'control: other sites, mean / median'],
            [[b_['epoch'], f"{b_['test_heldout'][0]:.1f} / {b_['test_heldout'][1]:.1f}", f"{c_['test_heldout'][0]:.1f} / {c_['test_heldout'][1]:.1f}", f"{b_['test_other'][0]:.1f} / {b_['test_other'][1]:.1f}", f"{c_['test_other'][0]:.1f} / {c_['test_other'][1]:.1f}"] for b_, c_ in zip(cp['site_disjoint'], cp['control'])])
        A('Site-disjoint run, all epochs (same monitoring): ' + '; '.join(f"ep {b_['epoch']}: held-out {b_['test_heldout'][0]:.1f} / {b_['test_heldout'][1]:.1f}, other {b_['test_other'][0]:.1f} / {b_['test_other'][1]:.1f}" for b_ in cp['site_disjoint_all_epochs']) + ' deg.\n')
    V = ret['single_image_val_and_all_test_images']; A('Single-image error of the raw-view network on images that no model was trained on (mean / median, deg):\n')
    tab(['model', f"val buildings in held-out sites ({list(V.values())[0]['heldout']['buildings']})", f"val buildings in other sites ({list(V.values())[0]['other']['buildings']})", 'all cached test images, held-out sites', 'all cached test images, other sites'],
        [[k, f"{v['heldout']['mean']:.1f} / {v['heldout']['median']:.1f}", f"{v['other']['mean']:.1f} / {v['other']['median']:.1f}", f"{v['test_images_heldout']['mean']:.1f} / {v['test_images_heldout']['median']:.1f}", f"{v['test_images_other']['mean']:.1f} / {v['test_images_other']['median']:.1f}"] for k, v in V.items()])
    if 'heldout_image_covariates_B' in ret:
        A('Site-disjoint raw-view network, single test images of the held-out sites, by image covariate (mean / median error, deg):\n')
        for nm, rows in ret['heldout_image_covariates_B'].items(): tab([nm, 'images', 'mean', 'median', '> 45 deg'], [[r['bin'], r['n'], f"{r['mean']:.1f}", f"{r['median']:.1f}", p1(r['gt45']) + ' %'] for r in rows])

# ------------------------------------------------------------------ photometric sensitivity
if sens:
    A('## 5. Photometric sensitivity (archived networks, inference only)\n')
    A(f"{sens['n_images']:,} unique test images from {sens['n_buildings']} buildings (random sample, seed 0), perturbed at the network input scale (448 x 256). Error against the true heading; \"shift\" = change of the prediction relative to the clean image (mean absolute, and signed circular mean). Training used only a mild global jitter (gain 0.8-1.2, offset +-20 grey levels). Check of the wrappers against the archived predictions: mean |difference| raw-view {sens['check_vs_archived']['raw_view_mean_abs_diff']:.3f} deg, nadir-rectified {sens['check_vs_archived']['nadir_mean_abs_diff']:.3f} deg.\n")
    rows = []
    for nm, r in sens['conditions'].items():
        row = [nm]
        for k in ('raw-view', 'nadir-rectified', 'ensemble'): v = r[k]; row += [f"{v['mae']:.2f} / {v['median']:.2f}", p1(v['gt45']) + ' %', f"{v['shift_abs_mean']:.2f} ({v['shift_signed_mean']:+.2f})"]
        e_ = r['ensemble']; row += [f"{e_['kappa_ratio']:.2f}", p1(e_.get('stays_within_30deg', float('nan'))) + ' %', p1(e_.get('flips_180_within_30deg', float('nan'))) + ' %']; rows.append(row)
